#include <iostream>
#include <string>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);
    while (user_input.length() > 2 && user_input.substr(1, user_input.length() - 2).find("dot") != std::string::npos) {
        size_t start_pos = user_input.find("dot", 1);
        if (start_pos == std::string::npos) break;
        user_input.replace(start_pos, 3, ".");
    }
    size_t at_pos = user_input.find("at", 1);
    if (at_pos != std::string::npos) {
        user_input.replace(at_pos, 2, "@");
    }
    std::cout << user_input << std::endl;
    return 0;
}
